#!/usr/bin/env node
/**
 * Regenerates src/core/generated/openapi.ts from the backend's swagger.json.
 *
 *   pnpm generate:types <path/to/swagger.json>
 *
 * The spec path (or $BB_SWAGGER) is required.
 * Only the public store endpoints are kept, with the definitions they reach,
 * so the generated file describes exactly what the SDK may call and nothing
 * that needs a login. The spec is Swagger 2.0; openapi-typescript reads
 * OpenAPI 3, so it is converted with swagger2openapi first.
 */
import { createRequire } from "node:module";
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";

const require = createRequire(import.meta.url);
const swagger2openapi = require("swagger2openapi");

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "..");
const specArg = process.argv[2] ?? process.env.BB_SWAGGER;
if (!specArg) {
  console.error(
    "Usage: pnpm generate:types <path/to/swagger.json>  (or set BB_SWAGGER)"
  );
  process.exit(1);
}
const specPath = resolve(specArg);
const outPath = resolve(root, "src/core/generated/openapi.ts");

/** The routes the SDK exposes: public, no auth, CORS open. */
const PUBLIC_ROUTES = [
  ["get", "/api/v1/public/stores/{storeId}"],
  ["get", "/api/v1/public/stores/{storeId}/listings"],
  ["get", "/api/v1/public/stores/{storeId}/listings/{listingId}"],
  ["post", "/api/v1/public/stores/{storeId}/uploads"],
  ["post", "/api/v1/public/stores/{storeId}/shipping-options"],
  ["post", "/api/v1/public/stores/{storeId}/quote"],
  ["post", "/api/v1/public/stores/{storeId}/checkout"],
  ["get", "/api/v1/public/orders/{token}"],
  ["get", "/api/v1/public/orders/{token}/receipt"],
];
/**
 * The error bodies the SDK types its refusals with (src/core/types.ts). The
 * routes reach them today; they are kept by name too, so a spec that stops
 * declaring them on a route still generates them, and one without them fails.
 */
const REQUIRED_DEFINITIONS = [
  "handlers.ValidationErrorResponse",
  "handlers.PublicRateLimitedResponse",
  "handlers.OrderReceiptConflictResponse",
  "handlers.PublicOrderLineItemResponse",
  "errors.ValidationErrorCode",
];

const spec = JSON.parse(readFileSync(specPath, "utf8"));
if (spec.swagger !== "2.0" && !spec.openapi) {
  console.error(`${specPath} is not a Swagger/OpenAPI document`);
  process.exit(1);
}

const paths = {};
for (const [method, route] of PUBLIC_ROUTES) {
  const op = spec.paths?.[route]?.[method];
  if (!op) {
    console.error(`Missing ${method.toUpperCase()} ${route} in ${specPath}`);
    process.exit(1);
  }
  paths[route] = { ...paths[route], [method]: op };
}

const definitions = spec.definitions ?? {};
const keep = new Set();
const walk = (node) => {
  if (Array.isArray(node)) return node.forEach(walk);
  if (!node || typeof node !== "object") return;
  for (const [key, value] of Object.entries(node)) {
    if (key === "$ref" && typeof value === "string") {
      const name = decodeURIComponent(value.replace("#/definitions/", ""));
      if (!keep.has(name) && definitions[name]) {
        keep.add(name);
        walk(definitions[name]);
      }
    } else walk(value);
  }
};
walk(paths);
for (const name of REQUIRED_DEFINITIONS) {
  if (!definitions[name]) {
    console.error(`Missing definition ${name} in ${specPath}`);
    process.exit(1);
  }
  walk({ $ref: `#/definitions/${name}` });
}

const filtered = {
  swagger: "2.0",
  info: {
    title: "BookingButler public store API",
    version: spec.info?.version ?? "1.0",
  },
  basePath: "/",
  paths,
  definitions: Object.fromEntries(
    [...keep].sort().map((name) => [name, definitions[name]])
  ),
};

const { openapi } = await swagger2openapi.convertObj(filtered, {
  patch: true,
  warnOnly: true,
});
const ast = await openapiTS(openapi, {
  alphabetize: true,
  // Enums stay string unions; the SDK exports its own readable constants.
  enum: false,
});

const header = `/**
 * GENERATED by scripts/generate-types.mjs from swagger.json — do not edit.
 * Only the public store endpoints and the schemas they reach.
 * Regenerate with \`pnpm generate:types <path/to/swagger.json>\`.
 */
/* eslint-disable */
`;
mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(outPath, header + astToString(ast));
console.log(
  `Wrote ${outPath}: ${Object.keys(paths).length} routes, ${keep.size} schemas (from ${specPath})`
);
